# =============================================================================
#  apply_pyai_patch.ps1
#  Brings a local py-ai (PyPI: py-for-ai) project to the 0.4.0 state.
#
#  What it does (all file contents are embedded in this script as Base64):
#    - CREATES:     .github/workflows/tests.yml, verify_all.py,
#                   src/py_ai/stripping.py, 5 new test files, src/py_ai/py.typed
#    - OVERWRITES:  src/py_ai/{__init__,cli,core,filters,formatting,readers}.py,
#                   7 existing test files, pyproject.toml, README.md, CHANGELOG.md
#    - RESTORES if missing: src/py_ai/__main__.py, tests/conftest.py
#    - REMOVES obsolete: verify_all.ps1, verify_all.sh (replaced by verify_all.py;
#                   they are backed up first, not lost)
#    - Backs up every overwritten file to _backup_pyai_patch\
#
#  The script is IDEMPOTENT: files that already have the new content are
#  skipped, so it is safe to run it repeatedly.
#
#  This script is 100% ASCII and carries every payload as Base64, so it is
#  immune to codepage / BOM / copy-paste encoding corruption.
#
#  Target: any local py-ai checkout (0.1.x - 0.4.x) - every patched file is
#  replaced with the full 0.4.0 content (previous versions backed up).
#
#  Usage (from anywhere):
#    powershell -ExecutionPolicy Bypass -File .\apply_pyai_patch.ps1 -ProjectRoot C:\path\to\py-ai
#    .\apply_pyai_patch.ps1 -ProjectRoot .            # if run from repo root
#    .\apply_pyai_patch.ps1 -DryRun                   # show actions only
#    .\apply_pyai_patch.ps1 -RunTests                 # run pytest at the end
#
#  Compatible with Windows PowerShell 5.1+ and PowerShell 7+ (pwsh).
#  All written files use UTF-8 (no BOM) and LF line endings.
# =============================================================================

param(
    [string]$ProjectRoot = ".",
    [switch]$DryRun,
    [switch]$RunTests
)

$ErrorActionPreference = "Stop"
$TargetVersion = "0.4.0"
$script:written  = 0
$script:skipped  = 0
$script:failures = 0
$script:backupDir = $null

function Info($m) { Write-Host "  [INFO] $m" }
function Ok($m)   { Write-Host "  [OK]   $m" -ForegroundColor Green }
function SkipM($m){ Write-Host "  [SKIP] $m" -ForegroundColor DarkGray }
function WarnM($m){ Write-Host "  [WARN] $m" -ForegroundColor Yellow }
function Bad($m)  { Write-Host "  [FAIL] $m" -ForegroundColor Red }

function Write-PatchFile {
    param(
        [string]$RelPath,
        [string]$Action = "update",   # create | ensure | update
        [string[]]$B64                # Base64 chunk(s) of the UTF-8 content
    )
    try {
        $full = Join-Path $script:Root $RelPath
        $dir  = Split-Path -Parent $full
        if (-not (Test-Path -LiteralPath $dir)) {
            New-Item -ItemType Directory -Force -Path $dir | Out-Null
        }
        # Decode the payload (ASCII transport -> exact original UTF-8 bytes).
        $joined = ($B64 -join "")
        $newContent = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($joined))
        # Normalize to LF.
        $newContent = $newContent -replace "`r`n", "`n"
        if ($newContent.Length -gt 0 -and -not $newContent.EndsWith("`n")) {
            $newContent = $newContent + "`n"
        }

        $exists = Test-Path -LiteralPath $full
        if ($exists -and $Action -eq "ensure") {
            SkipM "$RelPath (already present)"
            $script:skipped++
            return
        }
        if ($exists) {
            $old     = [System.IO.File]::ReadAllText($full)
            $oldNorm = $old -replace "`r`n", "`n"
            if ($oldNorm -ceq $newContent) {
                SkipM "$RelPath (already up to date)"
                $script:skipped++
                return
            }
            # Different content: back up the current version first.
            if ($null -eq $script:backupDir) {
                $script:backupDir = Join-Path $script:Root "_backup_pyai_patch"
            }
            $backupFile = Join-Path $script:backupDir $RelPath
            $bdir = Split-Path -Parent $backupFile
            if (-not (Test-Path -LiteralPath $bdir)) {
                New-Item -ItemType Directory -Force -Path $bdir | Out-Null
            }
            if (-not (Test-Path -LiteralPath $backupFile)) {
                Copy-Item -LiteralPath $full -Destination $backupFile -Force
            }
            if ($DryRun) {
                Info "[dry-run] would update $RelPath (current version backed up)"
                $script:written++
                return
            }
            [System.IO.File]::WriteAllText($full, $newContent, (New-Object System.Text.UTF8Encoding($false)))
            Ok "$RelPath updated (previous version backed up)"
            $script:written++
        }
        else {
            if ($DryRun) {
                Info "[dry-run] would create $RelPath"
                $script:written++
                return
            }
            [System.IO.File]::WriteAllText($full, $newContent, (New-Object System.Text.UTF8Encoding($false)))
            Ok "$RelPath created"
            $script:written++
        }
    }
    catch {
        Bad "$RelPath : $($_.Exception.Message)"
        $script:failures++
    }
}

function Remove-ObsoleteFile {
    param([string]$RelPath)
    try {
        $full = Join-Path $script:Root $RelPath
        if (-not (Test-Path -LiteralPath $full)) {
            SkipM "$RelPath (already absent)"
            $script:skipped++
            return
        }
        if ($null -eq $script:backupDir) {
            $script:backupDir = Join-Path $script:Root "_backup_pyai_patch"
        }
        $backupFile = Join-Path $script:backupDir $RelPath
        $bdir = Split-Path -Parent $backupFile
        if (-not (Test-Path -LiteralPath $bdir)) {
            New-Item -ItemType Directory -Force -Path $bdir | Out-Null
        }
        if (-not (Test-Path -LiteralPath $backupFile)) {
            Copy-Item -LiteralPath $full -Destination $backupFile -Force
        }
        if ($DryRun) {
            Info "[dry-run] would remove $RelPath (backed up)"
            $script:written++
            return
        }
        Remove-Item -LiteralPath $full -Force
        Ok "$RelPath removed (replaced by verify_all.py; backup kept)"
        $script:written++
    }
    catch {
        Bad "$RelPath : $($_.Exception.Message)"
        $script:failures++
    }
}

# ---------------------------------------------------------------- header
Write-Host "==============================================="
Write-Host " py-ai -> $TargetVersion patch"
Write-Host "==============================================="
if ($DryRun) { Info "DRY RUN mode - no files will be written" }

# ---------------------------------------------------------------- checks
try {
    $script:Root = (Resolve-Path -LiteralPath $ProjectRoot -ErrorAction Stop).Path
} catch {
    Bad "Project root '$ProjectRoot' does not exist: $($_.Exception.Message)"
    exit 1
}
Info "Project root: $script:Root"

$pyprojectPath = Join-Path $script:Root "pyproject.toml"
if (-not (Test-Path -LiteralPath $pyprojectPath)) {
    Bad "pyproject.toml not found in '$script:Root'."
    Bad "Run this script from the py-ai project root or pass -ProjectRoot <path>."
    exit 1
}
$pyproject = [System.IO.File]::ReadAllText($pyprojectPath)
if ($pyproject -notmatch 'name\s*=\s*"py-for-ai"') {
    Bad "pyproject.toml does not look like the py-for-ai project (name mismatch)."
    exit 1
}
$currentVersion = "unknown"
if ($pyproject -match 'version\s*=\s*"([^"]+)"') { $currentVersion = $Matches[1] }

if ($currentVersion -eq $TargetVersion) {
    Info "Project already at $TargetVersion - verifying file contents (idempotent run)."
} else {
    Info "Detected version $currentVersion - patching to $TargetVersion (everything backed up first)."
}

Write-PatchFile -RelPath ".github/workflows/tests.yml" -Action "create" -B64 @(
''
)

Write-PatchFile -RelPath "verify_all.py" -Action "create" -B64 @(
''
)

Write-PatchFile -RelPath "src/py_ai/stripping.py" -Action "create" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_formatting.py" -Action "create" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_include.py" -Action "create" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_json_format.py" -Action "create" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_stripping.py" -Action "create" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_budget_dryrun.py" -Action "create" -B64 @(
''
)

Write-PatchFile -RelPath "src/py_ai/__main__.py" -Action "ensure" -B64 @(
'IiIiCkVudHJ5IHBvaW50IGZvciBydW5uaW5nIHRoZSB1dGlsaXR5IGFzIGEgbW9kdWxlOiBgcHl0aG9uIC1tIHB5X2FpYAoiIiIKZnJvbSBweV9haS5jbGkgaW1wb3J0IG1haW4KCmlmIF9fbmFtZV9fID09ICJfX21haW5fXyI6CiAgICBtYWluKCkK'
)

Write-PatchFile -RelPath "tests/conftest.py" -Action "ensure" -B64 @(
''
)

Write-PatchFile -RelPath "src/py_ai/__init__.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "src/py_ai/cli.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "src/py_ai/core.py" -Action "update" -B64 @(
'',
'',
''
)

Write-PatchFile -RelPath "src/py_ai/filters.py" -Action "update" -B64 @(
'',
''
)

Write-PatchFile -RelPath "src/py_ai/formatting.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "src/py_ai/readers.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_cli.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_core_pack.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_edge_cases.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_filters.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_readers.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "tests/test_symlinks.py" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "pyproject.toml" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "README.md" -Action "update" -B64 @(
''
)

Write-PatchFile -RelPath "CHANGELOG.md" -Action "update" -B64 @(
'',
''
)

Write-PatchFile -RelPath "src/py_ai/py.typed" -Action "create" -B64 @('')

Remove-ObsoleteFile -RelPath "verify_all.ps1"

Remove-ObsoleteFile -RelPath "verify_all.sh"

# ---------------------------------------------------------------- chmod
if ($script:failures -eq 0 -and -not $DryRun) {
    try {
        $sh = Get-Command chmod -ErrorAction SilentlyContinue
        if ($sh) {
            & chmod +x (Join-Path $script:Root "verify_all.py")
        }
    } catch { }
}

# ---------------------------------------------------------------- verify
$py = $null
try { $py = Get-Command python -ErrorAction SilentlyContinue } catch { }
if (-not $py) { try { $py = Get-Command python3 -ErrorAction SilentlyContinue } catch { } }

if ($py -and -not $DryRun) {
    Push-Location $script:Root
    try {
        & python -m compileall -q src tests 2>$null
        if ($LASTEXITCODE -eq 0) { Ok "python -m compileall (src, tests)" }
        else { Bad "python -m compileall reported errors"; $script:failures++ }
    } catch {
        Bad "compileall failed: $($_.Exception.Message)"; $script:failures++
    }
    Pop-Location
} elseif (-not $py) {
    WarnM "python not found in PATH - compile check skipped"
}

if ($RunTests) {
    if ($py) {
        Push-Location $script:Root
        Info "Running pytest (this can take a minute)..."
        try {
            & python -m pytest -q
            if ($LASTEXITCODE -eq 0) { Ok "pytest" }
            else { Bad "pytest reported failures"; $script:failures++ }
        } catch {
            Bad "pytest failed: $($_.Exception.Message)"; $script:failures++
        }
        Pop-Location
    } else {
        WarnM "python not found - cannot run tests"
    }
}

# ---------------------------------------------------------------- summary
Write-Host ""
Write-Host "==============================================="
if ($DryRun) {
    Write-Host " DRY RUN summary: $script:written file(s) would be written, $script:skipped already up to date, $script:failures failure(s)"
} else {
    Write-Host " Summary: $script:written file(s) written, $script:skipped already up to date, $script:failures failure(s)"
}
if ($null -ne $script:backupDir) {
    Write-Host " Backups of overwritten files: $script:backupDir"
}
Write-Host "==============================================="
if (-not $DryRun -and $script:written -gt 0) {
    Write-Host ""
    Write-Host " Next steps:"
    Write-Host "   1. pip install -e `".[dev]`""
    Write-Host "   2. pytest                       (or re-run this script with -RunTests)"
    Write-Host "   3. python verify_all.py         (full pre-release verification, any OS)"
    Write-Host "   4. git add -A; git commit -m 'release $TargetVersion'"
}

if ($script:failures -gt 0) { exit 1 }
exit 0
